WITH params AS (SELECT max(snapshot_date) as max_filtered_date, today() as sys_today FROM gold.rmv_l5_task_completion_phys WHERE (snapshot_date = toDate('2025-12-31')) AND vx_type = 'V1'), calc_anchor AS (SELECT CASE WHEN max_filtered_date >= sys_today THEN sys_today ELSE max_filtered_date END as anchor_dt FROM params), anchor AS (SELECT anchor_dt FROM calc_anchor LIMIT 1) SELECT 'Month' as granularity, formatDateTime((SELECT anchor_dt FROM anchor), '%b.') as period_name, 1 as sort_order, vx_type, '' as region, '' as plant, '' as factory, '' as line, (SELECT anchor_dt FROM anchor) as filter_date, (SELECT anchor_dt FROM anchor) as snapshot_date_real, bitmapCardinality(groupBitmapMergeState(total_task)) as total_qty, bitmapCardinality(groupBitmapMergeState(todo_monthly)) as todo_qty, bitmapCardinality(groupBitmapMergeState(doing_monthly)) as doing_qty, bitmapCardinality(bitmapOr(groupBitmapMergeState(doing_monthly), groupBitmapMergeState(done_monthly))) as doing_done_qty, bitmapCardinality(groupBitmapMergeState(done_monthly)) as done_qty, bitmapCardinality(groupBitmapMergeState(acc)) as acc_qty, bitmapCardinality(groupBitmapMergeState(acc_total_task)) as acc_total_qty FROM gold.rmv_l5_task_completion_phys WHERE snapshot_date BETWEEN toStartOfMonth((SELECT anchor_dt FROM anchor)) AND (SELECT anchor_dt FROM anchor) AND vx_type = 'V1' GROUP BY vx_type UNION ALL SELECT 'Week' as granularity, concat('W', toString(iso_week)) as period_name, CASE WHEN iso_week = toISOWeek((SELECT anchor_dt FROM anchor)) THEN 2 WHEN iso_week = toISOWeek((SELECT anchor_dt FROM anchor) - INTERVAL 7 DAY) THEN 3 ELSE 4 END as sort_order, vx_type, '' as region, '' as plant, '' as factory, '' as line, (SELECT anchor_dt FROM anchor) as filter_date, max(snapshot_date) as snapshot_date_real, bitmapCardinality(groupBitmapMergeState(total_task)) as total_qty, bitmapCardinality(groupBitmapMergeState(todo_weekly)) as todo_qty, bitmapCardinality(groupBitmapMergeState(doing_weekly)) as doing_qty, bitmapCardinality(bitmapOr(groupBitmapMergeState(doing_weekly), groupBitmapMergeState(done_weekly))) as doing_done_qty, bitmapCardinality(groupBitmapMergeState(done_weekly)) as done_qty, bitmapCardinality(groupBitmapMergeState(acc)) as acc_qty, bitmapCardinality(groupBitmapMergeState(acc_total_task)) as acc_total_qty FROM gold.rmv_l5_task_completion_phys WHERE snapshot_date BETWEEN ((SELECT anchor_dt FROM anchor) - INTERVAL 20 DAY) AND (SELECT anchor_dt FROM anchor) AND ((iso_week = toISOWeek((SELECT anchor_dt FROM anchor)) AND iso_year = toISOYear((SELECT anchor_dt FROM anchor))) OR (iso_week = toISOWeek((SELECT anchor_dt FROM anchor) - INTERVAL 7 DAY) AND iso_year = toISOYear((SELECT anchor_dt FROM anchor) - INTERVAL 7 DAY)) OR (iso_week = toISOWeek((SELECT anchor_dt FROM anchor) - INTERVAL 14 DAY) AND iso_year = toISOYear((SELECT anchor_dt FROM anchor) - INTERVAL 14 DAY))) AND vx_type = 'V1' GROUP BY vx_type, period_name, sort_order UNION ALL SELECT 'Day' as granularity, toString(snapshot_date) as period_name, 5 + dateDiff('day', snapshot_date, (SELECT anchor_dt FROM anchor)) as sort_order, vx_type, '' as region, '' as plant, '' as factory, '' as line, (SELECT anchor_dt FROM anchor) as filter_date, snapshot_date as snapshot_date_real, bitmapCardinality(groupBitmapMergeState(total_task)) as total_qty, bitmapCardinality(groupBitmapMergeState(todo_daily)) as todo_qty, bitmapCardinality(groupBitmapMergeState(doing_daily)) as doing_qty, bitmapCardinality(bitmapOr(groupBitmapMergeState(doing_daily), groupBitmapMergeState(done_daily))) as doing_done_qty, bitmapCardinality(groupBitmapMergeState(done_daily)) as done_qty, bitmapCardinality(groupBitmapMergeState(acc)) as acc_qty, bitmapCardinality(groupBitmapMergeState(acc_total_task)) as acc_total_qty FROM gold.rmv_l5_task_completion_phys WHERE snapshot_date BETWEEN ((SELECT anchor_dt FROM anchor) - INTERVAL 6 DAY) AND (SELECT anchor_dt FROM anchor) AND vx_type = 'V1' GROUP BY vx_type, snapshot_date UNION ALL SELECT 'FilterRef' as granularity, '' as period_name, 99 as sort_order, '' as vx_type, '' as region, '' as plant, '' as factory, '' as line, (SELECT anchor_dt FROM anchor) as filter_date, (SELECT anchor_dt FROM anchor) as snapshot_date_real, 0 as total_qty, 0 as todo_qty, 0 as doing_qty, 0 as doing_done_qty, 0 as done_qty, 0 as acc_qty, 0 as acc_total_qty;
